+public class ServiceMetricCollector {
+
+    @RuntimeType
+    public Object intercept(@This Object obj,
+        @AllArguments Object[] allArguments,
+        @SuperCall Callable<?> zuper,
+        @Origin Method method
+    ) throws Throwable {
+        return zuper.call();
+    }
+}
